<script lang="ts">
 import {untrack} from 'svelte';
 import type {ToolState} from '../../types';
 import Result from '../../components/Result.svelte';
 let {state=$bindable()}: {state:ToolState} = $props();
 import {electricity} from './logic';untrack(()=>{state.tariff??=31;state.devices??=[{name:'ヒーター',watts:1000,hours:2,days:30}];});let result=$derived.by(()=>{try{return {value:electricity(state.devices,state.tariff),error:''};}catch(e){return {value:null,error:(e as Error).message};}});const format=(v:any)=>['day','month','year'].map((key,i)=>`${['1日','1か月','1年'][i]}: ${v[key].kwh.toFixed(3)} kWh / ${v[key].yen.toFixed(2)} 円`).join('\n');
</script>
<label>電力量単価 (円/kWh)<input type="number" min="0" max="10000" step="any" bind:value={state.tariff}/></label>{#each state.devices as device,i}<fieldset><legend>機器 {i+1}</legend><div class="form-grid"><label>名前<input bind:value={device.name} maxlength="100"/></label><label>消費電力 (W)<input type="number" min="0" max="1000000" step="any" bind:value={device.watts}/></label><label>1日の使用時間 (h)<input type="number" min="0" max="24" step="any" bind:value={device.hours}/></label><label>月の使用日数<input type="number" min="0" max="31" step="any" bind:value={device.days}/></label></div><button disabled={state.devices.length===1} onclick={()=>state.devices.splice(i,1)}>機器 {i+1} を削除</button>{#if result.value}<Result text={format(result.value.items[i])}/>{/if}</fieldset>{/each}<button disabled={state.devices.length>=20} onclick={()=>state.devices.push({name:'機器',watts:100,hours:1,days:30})}>機器を追加</button>{#if result.error}<p class="error" role="alert">{result.error}</p>{/if}{#if result.value}<h2 style="font-size:16px">全機器の合計</h2><Result text={format(result.value.total)}/>{/if}<p class="tool-note">例：1,000Wを毎日2時間、月30日、31円/kWh → 月60kWh・1,860円。年は指定した月×12。1日は実際に使用する日の値。最大20機器。基本料金、燃料費調整、再エネ賦課金、段階料金、待機電力、機器の出力変動等を含まない概算です。</p>
